class Solution:

	def TotalWays(self, s1):
		mod = int(1000000000.0 + 7)
		s2 = 'GEEKS'
		dp = [[0 for i in range(len(s2) + 1)] for j in range(len(s1) + 1)]
		dp[0][0] = 1
		for i in range(1, len(s1) + 1):
			dp[i][0] = 1
		for i in range(1, len(s1) + 1):
			for j in range(1, len(s2) + 1):
				if s1[i - 1] == s2[j - 1]:
					dp[i][j] = (dp[i - 1][j - 1] + dp[i - 1][j]) % mod
				else:
					dp[i][j] = dp[i - 1][j]
		return dp[len(s1)][len(s2)]
